// [S1] Identity, Family & Consent — Family Members screen with Web-aligned Hero banner & cards.
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/auth_provider.dart';
import 'package:family_veda/providers/core_providers.dart';
import 'package:family_veda/providers/members_provider.dart';
import 'package:family_veda/theme/app_theme.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:family_veda/widgets/shared/member_card.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

class MembersScreen extends ConsumerWidget {
  const MembersScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final membersAsync = ref.watch(membersProvider);
    final activeId = ref.watch(activeMemberProvider);
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        child: membersAsync.when(
          loading: () => const LoadingStateView(label: 'Loading members'),
          error: (_, _) => ErrorRetryView(
            onRetry: () => ref.invalidate(membersProvider),
          ),
          data: (items) {
            return RefreshIndicator(
              onRefresh: () async => ref.invalidate(membersProvider),
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(
                  parent: BouncingScrollPhysics(),
                ),
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                children: [
                  // 1. Web-Aligned Royal Blue Hero Banner
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(20),
                    decoration: BoxDecoration(
                      gradient: const LinearGradient(
                        colors: [Color(0xFF0F52BA), Color(0xFF1976D2), Color(0xFF0288D1)],
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                      ),
                      borderRadius: BorderRadius.circular(18),
                      boxShadow: [
                        BoxShadow(
                          color: const Color(0xFF0F52BA).withValues(alpha: 0.35),
                          blurRadius: 16,
                          offset: const Offset(0, 6),
                        ),
                      ],
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                          decoration: BoxDecoration(
                            color: Colors.white.withValues(alpha: 0.2),
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: const Text(
                            'MEMBERSHIP',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.w800,
                              letterSpacing: 1.1,
                              color: Colors.white,
                            ),
                          ),
                        ),
                        const SizedBox(height: 8),
                        const Text(
                          'Family Members',
                          style: TextStyle(
                            fontSize: 22,
                            fontWeight: FontWeight.w800,
                            color: Colors.white,
                            letterSpacing: -0.3,
                          ),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          'Select an active member for records, triage and clinical support. Adult member records remain strictly private.',
                          style: TextStyle(
                            fontSize: 13,
                            color: Colors.white.withValues(alpha: 0.9),
                            height: 1.35,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 16),

                  // 2. Members List Section
                  if (items.isEmpty)
                    Container(
                      padding: const EdgeInsets.all(24),
                      decoration: BoxDecoration(
                        color: isDark ? AppColors.surfaceDark : AppColors.surface,
                        borderRadius: BorderRadius.circular(16),
                        border: Border.all(
                          color: isDark ? AppColors.borderDark : AppColors.border,
                        ),
                      ),
                      child: const EmptyStateView(
                        title: 'No family members yet',
                        message: 'Add a member from family setup or join an existing family.',
                      ),
                    )
                  else ...[
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text(
                          'ROSTER (${items.length})',
                          style: TextStyle(
                            fontSize: 11.5,
                            fontWeight: FontWeight.w800,
                            letterSpacing: 0.8,
                            color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                          ),
                        ),
                        Text(
                          'Tap to switch active member',
                          style: TextStyle(
                            fontSize: 11.5,
                            color: isDark ? AppColors.mutedDark : const Color(0xFF64748B),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    ...items.map(
                      (member) => Padding(
                        padding: const EdgeInsets.only(bottom: 10),
                        child: MemberCard(
                          member: member,
                          isActive: member.id == activeId,
                          onSelected: () async {
                            final userId = ref.read(authProvider).userId;
                            if (userId == null) return;
                            ref.read(activeMemberProvider.notifier).state = member.id;
                            try {
                              await ref
                                  .read(memberPreferenceStoreProvider)
                                  .writeActiveMemberId(
                                    userId: userId,
                                    memberId: member.id,
                                  );
                            } on Object {
                              if (!context.mounted) return;
                              ScaffoldMessenger.of(context).showSnackBar(
                                const SnackBar(
                                  content: Text(
                                    'Member selected for this session.',
                                  ),
                                ),
                              );
                            }
                            if (context.mounted) {
                              if (context.canPop()) {
                                context.pop();
                              } else {
                                context.go('/home');
                              }
                            }
                          },
                        ),
                      ),
                    ),
                  ],
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

